const input = Array.isArray($json) ? $json : [$json];
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''}`.toLowerCase();
  const subVertical = `${call.subVertical ?? 'other'}`.toLowerCase();
  const urgencyTerms = ['leak', 'flooding', 'no water', 'sparking', 'smoke', 'burning', 'tree on', 'power lines', 'sewage', 'gas smell', 'broken', 'stuck'];
  const afterHours = /T(17|18|19|20|21|22|23):/.test(call.callTime ?? '');
  const urgencyHits = urgencyTerms.filter((term) => text.includes(term)).length;
  const priorityScore = (afterHours ? 1 : 0) + (urgencyHits * 2) + (call.repeatCaller ? 1 : 0);
  return { ...call, subVertical, priorityScore, queue: priorityScore >= 4 ? 'call-now' : priorityScore >= 2 ? 'same-day' : 'next-business-block' };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
